create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
create function public.test_reject(command text,expected text[],label text) returns void language plpgsql as $$ declare rejected boolean:=false; begin begin execute command; exception when others then if sqlstate=any(expected) then rejected:=true; else raise; end if; end; if not rejected then raise exception 'FAILED: % did not reject',label; end if; raise notice 'PASS: %',label; end $$;
